import React, { useState, useEffect } from "react";
import { useParams, Link } from "react-router-dom";
// import axios from "axios"; // Tạm thời ẩn axios đi chờ Backend

// 1. Dùng lại MOCK DATA giống hệt bên trang Danh sách để khớp dữ liệu
const mockProducts = [
  {
    id: 1,
    name: "Điện thoại iPhone 15 Pro Max",
    price: "29.000.000",
    category: "DienThoai",
    description: "Màn hình 6.7 inch, chip A17 Pro siêu mạnh mẽ, camera 48MP sắc nét.",
    image: "https://via.placeholder.com/300",
    slug: "iphone-15-pro-max"
  },
  {
    id: 2,
    name: "Laptop MacBook Air M2",
    price: "25.000.000",
    category: "Laptop",
    description: "Chip M2 mượt mà, thiết kế siêu mỏng nhẹ, pin dùng cả ngày.",
    image: "https://via.placeholder.com/300",
    slug: "macbook-air-m2"
  },
  {
    id: 3,
    name: "Điện thoại Samsung Galaxy S24",
    price: "22.000.000",
    category: "DienThoai",
    description: "Tích hợp AI thông minh, viền siêu mỏng, thiết kế sang trọng.",
    image: "https://via.placeholder.com/300",
    slug: "samsung-galaxy-s24"
  },
  {
    id: 4,
    name: "Laptop Asus Vivobook 14",
    price: "15.000.000",
    category: "Laptop",
    description: "Màn hình OLED rực rỡ, cấu hình phục vụ cực tốt cho học tập và làm việc.",
    image: "https://via.placeholder.com/300",
    slug: "asus-vivobook-14"
  }
];

function ProductDetail() {
  const { slug } = useParams(); // Lấy chữ "slug" trên thanh địa chỉ URL xuống
  const [product, setProduct] = useState(null);

  useEffect(() => {
    // Logic tạm thời: Tìm sản phẩm trong mảng mock data trùng với slug trên URL
    // Sau này thay bằng: axios.get(`http://localhost:xxxx/products/${slug}`).then(...)
    const foundProduct = mockProducts.find(item => item.slug === slug);
    setProduct(foundProduct);
  }, [slug]);

  // Nếu gõ link tinh tinh không ra sản phẩm
  if (!product) {
    return (
      <div>
        <h2>Sản phẩm không tồn tại!</h2>
        <Link to="/products">
          <button>Quay lại danh sách</button>
        </Link>
      </div>
    );
  }

  // --- KHU VỰC HIỂN THỊ CHI TIẾT ---
  return (
    <div>
      <Link to="/products">
        <button>⬅ Quay lại danh sách</button>
      </Link>
      
      <hr />

      <h2>Chi tiết sản phẩm</h2>
      
      <div>
        <img src={product.image} alt={product.name} width="300" />
      </div>

      <div>
        <h3>{product.name}</h3>
        <p><strong>Giá:</strong> <span style={{ color: "red" }}>{product.price} VNĐ</span></p>
        <p><strong>Danh mục:</strong> {product.category}</p>
        <p><strong>Mô tả chi tiết:</strong> {product.description}</p>
        
        <br />
        <button>Thêm vào giỏ hàng</button>
      </div>
    </div>
  );
}

export default ProductDetail;
